name: SLO Report
on:
  workflow_dispatch:
  schedule:
    - cron: '0 12 * * *'

jobs:
  test-ydb-slo-action:
    runs-on: ubuntu-latest
    steps:
      - name: Test SLO Action
        run: echo "Running SLO test"

  remove-slo-label:
    needs: test-ydb-slo-action
    runs-on: ubuntu-latest
    steps:
      - name: Remove SLO label
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request?.number || context.payload.issue?.number;

            if (!prNumber) {
              console.log("No pull request number found");
              return;
            }

            try {
              await github.rest.issues.removeLabel({
                owner,
                repo,
                issue_number: prNumber,
                name: "SLO"
              });
              console.log(`Successfully removed SLO label from PR #${prNumber}`);
            } catch (error) {
              if (error.status === 404) {
                console.log(`Label SLO not found on PR #${prNumber}, continuing...`);
              } else {
                throw error;
              }
            }
